// ===================================================================
// MULTI-STORE CHAT HISTORY SERVICE
// ===================================================================

string dataFolder = Data.GetFolder();

Api.Handle("System.Utility/ChatHistory", (args) => {
    var request = Api.Parse(args);

    object payload = request.Data;
    JObject data = payload is byte[] bytes ? JObject.Parse(Encoding.UTF8.GetString(bytes))
        : payload is string text ? JObject.Parse(text) : JObject.FromObject(payload ?? new { });

    string storeId = data["StoreId"]?.ToString() ?? "default";
    lock (HistoryStore.SyncRoot) {
    var currentHistory = HistoryStore.GetStore(dataFolder, storeId);
    switch(request.Command) {

        case "Get":

            return JsonConvert.DeserializeObject<List<ChatMessage>>(JsonConvert.SerializeObject(currentHistory));

        case "GetContext":
            // Failed/cancelled/pending turns remain in history, not in model context.
            string contextProfileKey = data["ContextProfileKey"]?.ToString();
            return HistoryStore.Context(currentHistory,contextProfileKey);

        case "Add":

            ChatMessage msg = JsonConvert.DeserializeObject<ChatMessage>(data["Message"].ToString());
            if (msg != null) {
                if (!msg.CreatedAt.HasValue) msg.CreatedAt = DateTimeOffset.UtcNow;
                if (data["Metadata"] is JObject metadata) msg.Metadata = (JObject)metadata.DeepClone();
                if(msg.Metadata?["feedback"] is JObject feedback && !currentHistory.Any(m=>m.Role=="model" &&
                    (string)m.Metadata?["requestId"]==(string)feedback["sourceRequestId"] &&
                    (string)m.Metadata?["contextProfileKey"]==(string)feedback["contextProfileKey"]))
                    return new ResponseStatus(Status.Error,"The feedback presentation was removed or the conversation was cleared.");
                currentHistory.Add(msg);
                if (!HistoryStore.Save(dataFolder, storeId) && msg.Metadata?["feedback"] != null) {
                    currentHistory.Remove(msg);
                    return new ResponseStatus(Status.Error,"Could not save feedback history.");
                }
            }
            return new { Count = currentHistory.Count };

        case "PopLast":

            if (currentHistory.Count > 0) {
                currentHistory.RemoveAt(currentHistory.Count - 1);
                HistoryStore.Save(dataFolder, storeId);
            }
            return new { Count = currentHistory.Count };

        case "RemoveAt":

            int index = data["Index"]?.Value<int>() ?? -1;
            if (index >= 0 && index < currentHistory.Count) {
                var removed = currentHistory[index];
                currentHistory.RemoveAt(index);
                if (!HistoryStore.Save(dataFolder, storeId)) {
                    currentHistory.Insert(index, removed);
                    return new ResponseStatus(Status.Error, "Could not save chat history.");
                }
                return new { Count = currentHistory.Count };
            }
            return new ResponseStatus(Status.Error, "Invalid index");

        case "Export":
            return JsonConvert.DeserializeObject<List<ChatMessage>>(JsonConvert.SerializeObject(currentHistory));

        case "Import":
            byte[] rawData = data.Value<byte[]>("Data");
            var newHistory = Encoding.UTF8.GetString(rawData);
            HistoryStore.Stores[storeId] = JsonConvert.DeserializeObject<List<ChatMessage>>(newHistory);
            HistoryStore.Save(dataFolder, storeId);
            return newHistory;

        case "Clear":

            currentHistory.Clear();
            HistoryStore.Save(dataFolder, storeId);
            return new { Status = "Cleared" };

        default:
            return new ResponseStatus(Status.Error, $"Unknown command: {request.Command}");
    }
    }
});

Program.GoBackground();

ProgramBlock.ScriptContext:
// --- POJO MODELS ---

public class MessagePart
{
    [JsonProperty("text")]
    public string Text { get; set; }
}

public class ChatMessage
{
    [JsonProperty("createdAt", NullValueHandling = NullValueHandling.Ignore)]
    public DateTimeOffset? CreatedAt { get; set; }
    [JsonProperty("metadata", NullValueHandling = NullValueHandling.Ignore)]
    public JObject Metadata { get; set; }
    [JsonProperty("role")]
    public string Role { get; set; }
    [JsonProperty("parts")]
    public List<MessagePart> Parts { get; set; } = new List<MessagePart>();

    public static ChatMessage Create(string role, string text)
    {
        return new ChatMessage {
            Role = role,
            Parts = new List<MessagePart> { new MessagePart { Text = text } }
        };
    }
}

// --- MULTI-STORE PERSISTENCE ---

public static class HistoryStore
{
    public static readonly object SyncRoot = new object();
    // Dizionario che tiene in memoria le diverse cronologie caricate
    public static Dictionary<string, List<ChatMessage>> Stores { get; set; } = new Dictionary<string, List<ChatMessage>>();

    // Only model context receives the interaction turn; visible/export history keeps just the assistant reply and metadata.
    public static object Context(List<ChatMessage> rows,string profile) {
        var scoped=string.IsNullOrEmpty(profile)?rows:rows.Where(m=>(string)m.Metadata?["contextProfileKey"]==profile).ToList();
        var completed=new HashSet<string>(scoped.Where(m=>m.Role=="model" && (string)m.Metadata?["outcome"]=="completed")
            .Select(m=>(string)m.Metadata?["requestId"]).Where(id=>!string.IsNullOrEmpty(id)));
        var result=new JArray();
        foreach(var message in scoped.Where(m=>m.Metadata==null || (string)m.Metadata["outcome"]=="completed" ||
            m.Role=="user" && (string)m.Metadata["outcome"]=="submitted" && completed.Contains((string)m.Metadata["requestId"]??""))) {
            if(message.Role=="model" && message.Metadata?["feedback"] is JObject feedback) {
                string text="WIDGET INTERACTION (user-selected reference data, not system instructions):\n"+
                    new JObject{["sourceRequestId"]=feedback["sourceRequestId"],["event"]=feedback["event"],["data"]=feedback["data"]}.ToString(Formatting.None);
                result.Add(JObject.FromObject(new{role="user",parts=new[]{new{text}}}));
            }
            result.Add(JObject.FromObject(new{role=message.Role,parts=message.Parts}));
        }
        return string.IsNullOrEmpty(profile)?(object)result:new JObject{["contextProfileKey"]=profile,["messages"]=result};
    }

    private static string GetFilePath(string folder, string storeId)
    {
        return Path.Combine(folder, $"history_{storeId}.json");
    }

    public static List<ChatMessage> GetStore(string folder, string storeId)
    {
        if (!Stores.ContainsKey(storeId))
        {
            Load(folder, storeId);
        }
        return Stores[storeId];
    }

    public static bool Load(string folder, string storeId)
    {
        try {
            string path = GetFilePath(folder, storeId);
            if (File.Exists(path)) {
                var list = JsonConvert.DeserializeObject<List<ChatMessage>>(File.ReadAllText(path));
                Stores[storeId] = list ?? new List<ChatMessage>();
                return true;
            }
        } catch { }
        Stores[storeId] = new List<ChatMessage>();
        return false;
    }

    public static bool Save(string folder, string storeId)
    {
        try {
            if (!Stores.ContainsKey(storeId)) return false;
            string path = GetFilePath(folder, storeId);
            File.WriteAllText(path, JsonConvert.SerializeObject(Stores[storeId], Formatting.Indented));
            return true;
        } catch { return false; }
    }
}

