// ===================================================================
// HOMEGENIE PANEL NOTIFICATION SERVICE
// ===================================================================

string devicesPath = Path.Combine(Data.GetFolder(), "panel_devices.json");

// --- 1. API HANDLER
// HomeAutomation.HomeGenie/Config/Notifications.Register/<token>/<model>
Api.Handle("HomeAutomation.HomeGenie/Config/Notifications.Register", (args) => 
{
    var request = Api.Parse(args);
    string token = request.Domain;
    string model = WebUtility.UrlDecode(request.Address);

    if (string.IsNullOrEmpty(token)) return new ResponseStatus(Status.Error, "Token missing");

    var devices = DeviceRegistry.Load(devicesPath);
    var existing = devices.FirstOrDefault(d => d.Token == token);

    if (existing == null)
    {
        devices.Add(new PanelDevice { 
            Token = token, 
            Model = model, 
            RegisteredAt = DateTime.Now 
        });
        Program.Log.Info($"New Panel registered: {model} ({token})");
    }
    else 
    {
        existing.Model = model;
        existing.LastSeen = DateTime.Now;
    }

    DeviceRegistry.Save(devicesPath, devices);
    return new ResponseStatus(Status.Ok, "Registered");
});

// --- 2. EVENT LISTENER ---
When.ModuleParameterChanged((module, parameter) => 
{
    // Check if the module has the feature enabled
    if (module.HasFeature("HomeGeniePanel.Notifications")) {

        bool shouldNotify = false;
        string message = "";

        // Relevant parameter filtering logic
        switch (parameter.Name) {
            case "Status.Level":
                shouldNotify = true;
                string state = parameter.DecimalValue > 0 ? "ON" : "OFF";
                if (module.IsOfDeviceType("Shutter"))
                {
                    state = parameter.DecimalValue > 0 ? "OPEN" : "CLOSED";
                }
                message = $"{module.Instance.Name} is now {state}";
                break;

            case "Sensor.MotionDetect":
                if (parameter.DecimalValue > 0) 
                {
                    shouldNotify = true;
                    message = $"Motion detected in {module.Instance.Name}";
                }
                break;

            case "Sensor.DoorWindow":
                shouldNotify = true;
                message = $"{module.Instance.Name} is {(parameter.DecimalValue > 0 ? "Open" : "Closed")}";
                break;

            case "Sensor.Alarm":
            case "Sensor.ObjectDetect":
                if (parameter.DecimalValue > 0) 
                {
                    shouldNotify = true;
                    message = $"ALARM: {module.Instance.Name} detected activity!";
                }
                break;

            case "Status.DoorLock":
                shouldNotify = true;
                message = $"{module.Instance.Name} is {(parameter.DecimalValue > 0 ? "Locked" : "Unlocked")}";
                break;
        }

        if (shouldNotify) 
        {
            var devices = DeviceRegistry.Load(devicesPath);

            foreach (var device in devices) 
            {
                var targetDevice = device; // local capture

                Program.RunAsyncTask(async () => 
                {
                    try 
                    {
                        var payload = new 
                        { 
                            token = targetDevice.Token, 
                            title = "HomeGenie Update", 
                            body = message
                        };

                        string jsonPayload = Newtonsoft.Json.JsonConvert.SerializeObject(payload);

                        // Use static client instance instead of creating a new one for each request
                        var request = new HttpRequestMessage(HttpMethod.Post, "https://push.homegenie.workers.dev");
                        request.Headers.Add("x-hg-key", "PYKqr2hUhdASrkWJGWuKpM+C7rbXaQTFcvFYz4d8IJBLK1bz4R6kw1");
                        request.Content = new StringContent(jsonPayload, System.Text.Encoding.UTF8, "application/json");                            

                        var response = await HttpHelper.Client.SendAsync(request);

                        if (!response.IsSuccessStatusCode) {
                            string err = await response.Content.ReadAsStringAsync();
                            Program.Log.Error($"Proxy Error[{response.StatusCode}]: {err}");
                        } else {
                            Program.Log.Info($"Notification sent to {targetDevice.Model}");
                        }
                    }
                    catch (Exception ex)
                    {
                        Program.Log.Error($"Failed to send to proxy: {ex.Message}");
                    }
                });
            }
        }
    }
    return true;
});

Program.GoBackground();

