#using System.Net.Http

public class PanelDevice {
    public string Token { get; set; }
    public string Model { get; set; }
    public DateTime RegisteredAt { get; set; }
    public DateTime LastSeen { get; set; }
}

public static class DeviceRegistry {
    public static List<PanelDevice> Load(string path) {
        try {
            if (File.Exists(path)) {
                string json = File.ReadAllText(path);
                return JsonConvert.DeserializeObject<List<PanelDevice>>(json) ?? new List<PanelDevice>();
            }
        } catch { }
        return new List<PanelDevice>();
    }

    public static void Save(string path, List<PanelDevice> devices) {
        try {
            string json = JsonConvert.SerializeObject(devices, Formatting.Indented);
            File.WriteAllText(path, json);
        } catch { }
    }
}

public static class HttpHelper {
    public static readonly HttpClient Client = new HttpClient();
}

