// Normalize typed/legacy model outputs without executing actions.
Api.Handle("System.Utility/ActionExecutor/Response.Schema", input => GenieResponseContract.Schema());
Api.Handle("System.Utility/ActionExecutor/Response.Normalize", input => {
    try {
        string text = ReadActionResponse(input);
        JObject response;
        if (text.TrimStart().StartsWith("{")) response = JObject.Parse(text);
        else {
            var segments = ExtractResponse(text);
            var commands = CodeBlockExtractor.ExtractCommands(segments);
            response = new JObject { ["version"] = 1, ["kind"] = commands.Count > 0 ? "device" : "reply",
                ["explanation"] = string.Join("\n", segments.Where(s => !s.TrimStart().StartsWith("```api-call"))).Trim() };
            if (string.IsNullOrWhiteSpace((string)response["explanation"])) response["explanation"] = "Requested device actions.";
            if (commands.Count > 0) response["commands"] = new JArray(commands);
        }
        return (object)GenieResponseContract.Normalize(response);
    } catch (Exception ex) { return new { Status = "Error", Message = ex.Message }; }
});

// Shared action service; no model or inference engine is required.
Api.Handle("System.Utility/ActionExecutor/Extract", input => {
    return ExtractResponse(ReadActionResponse(input));
}).Handle("System.Utility/ActionExecutor/Execute", input => {
    return ExecuteActionRequest(input);
}).Handle("System.Utility/ActionExecutor/ExtractAndExecute", input => {
    return ExtractAndExecute(Api, ReadActionResponse(input));
}).Handle("System.Utility/ActionExecutor/Results", input => GetActionResults(input))
 .Handle("System.Utility/ActionExecutor/Program.Deploy", input => ExecuteProgramDeployment(input))
 .Handle("System.Utility/ActionExecutor/Program.Recover", input => ExecuteProgramDeployment(input, true));
Program.GoBackground();

