#using System.Text.RegularExpressions

public class ApiCommandExecution
{
    public int Index { get; set; }
    public string Command { get; set; }
    public bool Success { get; set; }
    public object Response { get; set; }
    public string Error { get; set; }
    public string ActionId { get; set; }
    public string RequestId { get; set; }
    public string State { get; set; }
    public long DurationMs { get; set; }
    public bool Replayed { get; set; }
    public DateTimeOffset? CompletedAt { get; set; }
}

public static class ActionLedger
{
    public static readonly object Gate = new object();
    public static Dictionary<string, ApiCommandExecution> Load(string folder)
    {
        string file = Path.Combine(folder, "action-results.json");
        return File.Exists(file)
            ? JsonConvert.DeserializeObject<Dictionary<string, ApiCommandExecution>>(File.ReadAllText(file))
                ?? throw new InvalidOperationException("Invalid action ledger.")
            : new Dictionary<string, ApiCommandExecution>();
    }
    public static void Save(string folder, Dictionary<string, ApiCommandExecution> records)
    {
        Directory.CreateDirectory(folder);
        string file = Path.Combine(folder, "action-results.json");
        string temporary = file + ".tmp";
        File.WriteAllText(temporary, JsonConvert.SerializeObject(records), new UTF8Encoding(false));
        File.Move(temporary, file, true);
    }
    public static ApiCommandExecution Copy(ApiCommandExecution result) =>
        JsonConvert.DeserializeObject<ApiCommandExecution>(JsonConvert.SerializeObject(result));
}

public List<ApiCommandExecution> ExecuteActionRequest(object input)
{
    string text = ReadActionResponse(input);
    JObject envelope = null;
    if (text.TrimStart().StartsWith("{")) {
        try {
            var parsed = JObject.Parse(text);
            if (parsed["requestId"] != null || parsed["actions"] != null || parsed["response"] != null) envelope = parsed;
        } catch (Newtonsoft.Json.JsonException) { }
    }
    string requestId = envelope?["requestId"]?.ToString() ?? Guid.NewGuid().ToString("N");
    if (!Regex.IsMatch(requestId, @"\A[A-Za-z0-9_-]{1,128}\z"))
        throw new InvalidOperationException("Invalid action request ID.");
    if (envelope?["actions"] != null && !(envelope["actions"] is JArray)) throw new InvalidOperationException("Invalid structured action list.");
    if (envelope?["actions"] is JArray typedActions && typedActions.Count == 1 &&
        new[] { "program-deploy", "program-recover" }.Contains(typedActions[0]["type"]?.ToString())) {
        var deployment = (JObject)typedActions[0].DeepClone(); deployment["requestId"] = requestId;
        return new List<ApiCommandExecution> { ExecuteProgramDeployment(deployment, deployment["type"].ToString() == "program-recover") };
    }
    var commands = new List<string>();
    if (envelope?["actions"] is JArray actions) {
        foreach (var action in actions) {
            if (action["type"]?.ToString() != "api-call") throw new InvalidOperationException("Unsupported action type.");
            string domain = action["target"]?["domain"]?.ToString();
            string address = action["target"]?["address"]?.ToString();
            string command = action["command"]?.ToString();
            if (!Regex.IsMatch(domain ?? "", @"\A[A-Za-z][A-Za-z0-9_.:-]*\z") ||
                !Regex.IsMatch(address ?? "", @"\A[^/\s]+\z") || !Regex.IsMatch(command ?? "", @"\A[^/\s]+\z"))
                throw new InvalidOperationException("Invalid structured action target.");
            var arguments = action["arguments"] as JArray ?? new JArray();
            if (arguments.Any(arg => arg.Type != JTokenType.String || arg.ToString().Contains('/') || arg.ToString().Contains('\n') || arg.ToString().Contains('\r')))
                throw new InvalidOperationException("Invalid structured action arguments.");
            commands.Add(domain + "/" + address + "/" + command + (arguments.Count == 0 ? "" : "/" + string.Join("/", arguments.Select(a => a.ToString()))));
        }
    } else {
        string response = envelope == null ? text : envelope["response"]?.Value<string>() ?? "";
        commands = CodeBlockExtractor.ExtractCommands(ExtractResponse(response));
    }
    return ExecuteApiCommands(Api, commands, requestId);
}

public List<ApiCommandExecution> ExecuteApiCommands(dynamic api, IEnumerable<string> proposedCommands, string requestId = null)
{
    requestId = requestId ?? Guid.NewGuid().ToString("N");
    var results = new List<ApiCommandExecution>();
    lock (ActionLedger.Gate) {
        string folder = Data.GetFolder();
        // A corrupt or unreadable ledger must prevent execution, never silently reset IDs.
        var records = ActionLedger.Load(folder);
        int index = 0;
        foreach (string proposed in proposedCommands ?? Enumerable.Empty<string>()) {
            string command = (proposed ?? "").Trim();
            if (command.StartsWith("/api/")) command = command.Substring(5);
            string actionId = requestId + ":" + index;
            if (records.TryGetValue(actionId, out var previous)) {
                var replay = ActionLedger.Copy(previous);
                replay.Replayed = true;
                if (previous.Command != command) {
                    replay.Command = command; replay.State = "failed"; replay.Success = false;
                    replay.Error = "Action ID is already assigned to a different command.";
                }
                results.Add(replay); index++; continue;
            }
            var result = new ApiCommandExecution { Index = index++, Command = command, ActionId = actionId,
                RequestId = requestId, State = "unknown", Error = "Execution may be in progress or interrupted; do not retry automatically." };
            results.Add(result);
            if (!Regex.IsMatch(command, @"\A[A-Za-z][A-Za-z0-9_.:-]*/[^/\s]+/[^/\s]+(?:/[^\r\n]*)?\z") || command.StartsWith("System.Utility/ActionExecutor/")) {
                result.State = "failed"; result.Error = "Invalid HomeGenie API command.";
                result.CompletedAt = DateTimeOffset.UtcNow; records[actionId] = result; ActionLedger.Save(folder, records); continue;
            }
            // Durable reservation before side effects: crash recovery retains unknown outcome.
            records[actionId] = result; ActionLedger.Save(folder, records);
            var timer = System.Diagnostics.Stopwatch.StartNew();
            try {
                bool configuring = command.StartsWith("HomeAutomation.HomeGenie/Config/Modules.ParameterSet/");
                if (configuring) GenieResponseContract.DeviceCommand(command);
                result.Response = configuring ? ModuleSettingAction.Execute(api, command) : api.Call(command);
                JToken response = null;
                if (result.Response != null) {
                    try { response = result.Response is string value ? JToken.Parse(value) : JToken.FromObject(result.Response); }
                    catch (Newtonsoft.Json.JsonException) { response = JValue.CreateString(result.Response.ToString()); }
                }
                string status = response is JObject obj ? (obj["Status"] ?? obj["response"]?["Status"])?.ToString() : null;
                if (configuring && (!(response is JObject configuration) || configuration["version"]?.Value<int>() != 1
                    || configuration["verified"]?.Value<bool>() != true || (string)configuration["value"] != command.Split('/')[6]
                    || (string)configuration["domain"] != command.Split('/')[3] || (string)configuration["address"] != command.Split('/')[4]
                    || (string)configuration["key"] != command.Split('/')[5]
                    || (string)configuration["state"] != "completed")) {
                    result.State = response is JObject rejected && (string)rejected["Status"] == "Error" && (string)rejected["state"] != "unknown" ? "failed" : "unknown";
                    result.Error = response?["Message"]?.ToString() ?? "Configuration was not verified.";
                }
                else if (result.Response == null) { result.State = "unknown"; result.Error = "API returned no result; execution outcome is unknown."; }
                else if ((string.Equals(status, "Error", StringComparison.OrdinalIgnoreCase) || status == "1")) {
                    result.State = "failed"; result.Error = (response["Message"] ?? response["response"]?["Message"])?.ToString() ?? "API command failed.";
                } else { result.State = "completed"; result.Success = true; result.Error = null; }
            } catch (Exception ex) {
                // Exceptions can occur after a side effect; they cannot prove failure.
                result.State = "unknown"; result.Error = "Execution outcome is unknown (" + ex.GetType().Name + ").";
            }
            result.DurationMs = timer.ElapsedMilliseconds; result.CompletedAt = DateTimeOffset.UtcNow;
            try { ActionLedger.Save(folder, records); }
            catch (Exception) {
                result.State = "unknown"; result.Success = false;
                result.Error = "Execution result could not be persisted; do not retry automatically.";
            }
        }
    }
    return results;
}

public List<ApiCommandExecution> GetActionResults(object input)
{
    string text = ReadActionResponse(input);
    string requestId = text;
    if (text.TrimStart().StartsWith("{")) requestId = JObject.Parse(text)["requestId"]?.ToString();
    if (!Regex.IsMatch(requestId ?? "", @"\A[A-Za-z0-9_-]{1,128}\z")) throw new InvalidOperationException("Invalid action request ID.");
    lock (ActionLedger.Gate) return ActionLedger.Load(Data.GetFolder()).Values.Where(r => r.RequestId == requestId)
        .OrderBy(r => r.Index).Select(ActionLedger.Copy).ToList();
}

public class CodeBlockExtractor
{
    public static List<string> ExtractInterleaved(string sourceText)
    {
        var result = new List<string>();
        if (string.IsNullOrEmpty(sourceText)) return result;
        // Mask reasoning while retaining source offsets and original display text.
        string visible = Regex.Replace(sourceText, @"<think\b[^>]*>[\s\S]*?(?:</think\s*>|$)",
            m => Regex.Replace(m.Value, @"[^\r\n]", " "), RegexOptions.IgnoreCase);
        var opening = new Regex(@"^[ \t]*(?<fence>`{3,}|~{3,})(?<label>[^\r\n]*)\r?\n", RegexOptions.Multiline);
        int cursor = 0, textStart = 0;
        while (cursor < visible.Length)
        {
            var start = opening.Match(visible, cursor);
            if (!start.Success) break;
            string fence = start.Groups["fence"].Value;
            var closing = new Regex(@"^[ \t]*" + Regex.Escape(fence[0].ToString()) + "{" + fence.Length + @",}[ \t]*\r?$", RegexOptions.Multiline);
            var end = closing.Match(visible, start.Index + start.Length);
            if (!end.Success) break;
            int blockEnd = end.Index + end.Length;
            if (fence[0] == '`' && start.Groups["label"].Value.Trim() == "api-call")
            {
                AddText(result, sourceText.Substring(textStart, start.Index - textStart));
                AddText(result, sourceText.Substring(start.Index, blockEnd - start.Index));
                textStart = blockEnd;
            }
            cursor = blockEnd;
        }
        AddText(result, sourceText.Substring(textStart));
        return result;
    }

    private static void AddText(List<string> result, string text)
    {
        if (!string.IsNullOrWhiteSpace(text)) result.Add(text.Trim());
    }

    public static List<string> ExtractCommands(IEnumerable<string> segments)
    {
        var commands = new List<string>();
        foreach (string segment in segments ?? Enumerable.Empty<string>())
        {
            var match = Regex.Match(segment ?? "", @"\A(?<fence>`{3,})api-call[ \t]*\r?\n(?<body>[\s\S]*?)\r?\n\k<fence>[ \t]*\z");
            if (!match.Success) continue;
            foreach (string line in match.Groups["body"].Value.Split(new[] {'\r', '\n'}, StringSplitOptions.RemoveEmptyEntries))
                if (!string.IsNullOrWhiteSpace(line)) commands.Add(line.Trim());
        }
        return commands;
    }
}

public string ReadActionResponse(object input)
{
    var request = Api.Parse(input);
    if (request.Data is byte[] bytes && bytes.Length > 0) return Encoding.UTF8.GetString(bytes);
    if (request.Data is string text && text.Length > 0) return text;
    if (request.Data != null && !(request.Data is byte[])) return JsonConvert.SerializeObject(request.Data);
    return WebUtility.UrlDecode(request.OriginalRequest ?? "");
}

public List<string> ExtractResponse(string response)
{
    return CodeBlockExtractor.ExtractInterleaved(response);
}


public List<string> ExtractAndExecute(dynamic api, string response) {
    var segments = ExtractResponse(response);
    ExecuteApiCommands(api, CodeBlockExtractor.ExtractCommands(segments));
    return segments;
}

// A deployment session owns its assigned program ID across compiler repair attempts.
public class ProgramDeploymentSession
{
    public string Mode { get; set; }
    public string Target { get; set; }
    public string ProgramId { get; set; }
    public JObject Original { get; set; }
    public string State { get; set; }
    public int Attempt { get; set; }
}

public JObject DeploymentJson(object value)
{
    if (value == null) throw new InvalidOperationException("The API returned no result.");
    var token = value is string text ? JToken.Parse(text) : JToken.FromObject(value);
    if (!(token is JObject obj)) throw new InvalidOperationException("Expected an API object.");
    return obj;
}

public void RequireDeploymentSuccess(object value)
{
    var obj = DeploymentJson(value);
    string status = (obj["Status"] ?? obj["response"]?["Status"])?.ToString();
    if (!string.Equals(status, "Ok", StringComparison.OrdinalIgnoreCase) && status != "0")
        throw new InvalidOperationException("The API did not confirm success.");
}

public JArray DeploymentCompilerErrors(object value)
{
    if (value == null) throw new InvalidOperationException("The compiler returned no result.");
    var token = value is string text ? JToken.Parse(text) : JToken.FromObject(value);
    if (token is JObject obj) token = obj["ResponseValue"] ?? obj["response"]?["ResponseValue"];
    if (token?.Type == JTokenType.String) token = JToken.Parse(token.ToString());
    if (!(token is JArray errors)) throw new InvalidOperationException("Invalid compiler response.");
    return errors;
}

public string DeploymentSessionFile(string requestId)
{
    string folder = Path.Combine(Data.GetFolder(), "program-deployments");
    Directory.CreateDirectory(folder);
    return Path.Combine(folder, requestId + ".json");
}

public void SaveDeploymentSession(string file, ProgramDeploymentSession session)
{
    File.WriteAllText(file + ".tmp", JsonConvert.SerializeObject(session), new UTF8Encoding(false));
    File.Move(file + ".tmp", file, true);
}

public ApiCommandExecution ExecuteProgramDeployment(object input, bool recover = false)
{
    var request = input is JObject supplied ? supplied : JObject.Parse(ReadActionResponse(input));
    string requestId = request["requestId"]?.Value<string>();
    if (!Regex.IsMatch(requestId ?? "", @"\A[A-Za-z0-9_-]{1,128}\z"))
        throw new InvalidOperationException("Invalid deployment request ID.");
    int attempt = recover ? 0 : request["attempt"]?.Value<int>() ?? 1;
    if (!recover && (attempt < 1 || attempt > 5)) throw new InvalidOperationException("Invalid deployment attempt.");
    string mode = request["mode"]?.Value<string>();
    string target = request["program_id"]?.Value<string>() ?? "";
    JObject program = request["program"] as JObject;
    if (!recover) {
        if (mode != "create" && mode != "update") throw new InvalidOperationException("Invalid deployment mode.");
        if ((mode == "create" && target.Length > 0) || (mode == "update" && !Regex.IsMatch(target, @"\A[1-9][0-9]*\z")))
            throw new InvalidOperationException("Invalid deployment target.");
        if (program == null || new[] { "name", "language", "setup", "main", "context", "description" }
            .Any(key => program[key] != null && program[key].Type != JTokenType.String))
            throw new InvalidOperationException("Invalid program sources.");
        if (string.IsNullOrWhiteSpace(program["name"]?.Value<string>()) || program["setup"] == null ||
            string.IsNullOrWhiteSpace(program["main"]?.Value<string>()) ||
            !new[] { "csharp", "python", "javascript" }.Contains(program["language"]?.Value<string>()))
            throw new InvalidOperationException("Incomplete program sources.");
        // Canonical payload includes every field that can change the installed program.
        program = new JObject(new[] { "name", "language", "setup", "main", "context", "description" }
            .Select(key => new JProperty(key, program[key]?.Value<string>() ?? "")));
    }
    string canonical = recover ? "recover" : new JObject {
        ["mode"] = mode, ["target"] = target, ["program"] = program
    }.ToString(Formatting.None);
    string fingerprint = Convert.ToHexString(System.Security.Cryptography.SHA256.HashData(Encoding.UTF8.GetBytes(canonical)));
    string command = "program-" + (recover ? "recover" : "deploy") + "/" + fingerprint;
    string actionId = requestId + ":" + (recover ? "recover" : "deploy-" + attempt);
    lock (ActionLedger.Gate) {
        string folder = Data.GetFolder();
        var records = ActionLedger.Load(folder);
        if (records.TryGetValue(actionId, out var previous)) {
            var replay = ActionLedger.Copy(previous); replay.Replayed = true;
            if (previous.Command != command) {
                replay.State = "failed"; replay.Success = false; replay.Error = "Deployment ID is assigned to a different payload.";
            }
            return replay;
        }
        string file = DeploymentSessionFile(requestId);
        var session = File.Exists(file)
            ? JsonConvert.DeserializeObject<ProgramDeploymentSession>(File.ReadAllText(file))
                ?? throw new InvalidOperationException("Invalid deployment session.")
            : null;
        if (!recover && session != null && (session.Mode != mode || session.Target != target))
            throw new InvalidOperationException("Deployment target cannot change during repair.");
        if (session != null && session.State == "unknown")
            throw new InvalidOperationException("Deployment outcome is unknown; automatic mutation is blocked.");
        if (!recover && session != null && (session.State != "compile_failed" || attempt != session.Attempt + 1))
            throw new InvalidOperationException("Only the next compiler repair attempt is allowed.");
        if (!recover && session == null && attempt != 1) throw new InvalidOperationException("Deployment must start at attempt 1.");
        if (recover && session == null) return new ApiCommandExecution {
            RequestId = requestId, ActionId = actionId, Command = command, State = "completed", Success = true,
            Response = new { status = "unchanged", program_id = "" }
        };
        var result = new ApiCommandExecution { RequestId = requestId, ActionId = actionId, Index = attempt,
            Command = command, State = "unknown", Error = "Deployment may be in progress; do not retry automatically." };
        records[actionId] = result; ActionLedger.Save(folder, records);
        var clock = System.Diagnostics.Stopwatch.StartNew();
        bool mutationStarted = false;
        try {
            if (session == null) {
                session = new ProgramDeploymentSession { Mode = mode, Target = target, ProgramId = target, State = "prepared" };
                if (mode == "update") {
                    var original = DeploymentJson(Api.Call("HomeAutomation.HomeGenie/Automation/Programs.Get/" + target));
                    if (original["Address"]?.ToString() != target || original["Group"]?.ToString() != "Automan")
                        throw new InvalidOperationException("Only existing Automan programs may be updated.");
                    session.Original = (JObject)original.DeepClone();
                }
                SaveDeploymentSession(file, session);
            }
            if (recover) {
                if (session.State == "completed") throw new InvalidOperationException("A completed deployment cannot be rolled back automatically.");
                if (session.Original != null) {
                    session.State = "unknown"; SaveDeploymentSession(file, session); mutationStarted = true;
                    var original = (JObject)session.Original.DeepClone(); original["IsEnabled"] = false;
                    var errors = DeploymentCompilerErrors(Api.Call("HomeAutomation.HomeGenie/Automation/Programs.Compile", original.ToString(Formatting.None)));
                    if (errors.Count > 0) throw new InvalidOperationException("The previous program could not be recompiled.");
                    if (session.Original["IsEnabled"]?.Value<bool>() == true)
                        RequireDeploymentSuccess(Api.Call("HomeAutomation.HomeGenie/Automation/Programs.Enable/" + session.ProgramId));
                    session.State = "restored";
                } else session.State = "retained_disabled";
                result.Response = new { status = session.State, program_id = session.ProgramId };
                result.State = "completed"; result.Success = true; result.Error = null;
            } else {
                session.Attempt = attempt; session.State = "unknown";
                SaveDeploymentSession(file, session);
                mutationStarted = true;
                if (session.ProgramId.Length == 0) {
                    var added = DeploymentJson(Api.Call("HomeAutomation.HomeGenie/Automation/Programs.Add", JsonConvert.SerializeObject(new {
                        Type = program["language"].Value<string>(), Group = "Automan", Name = program["name"].Value<string>(),
                        Description = program["description"].Value<string>(), IsEnabled = false
                    })));
                    string id = (added["ResponseValue"] ?? added["response"]?["ResponseValue"])?.ToString();
                    if (!Regex.IsMatch(id ?? "", @"\A[1-9][0-9]*\z")) throw new InvalidOperationException("Unable to obtain the new program ID.");
                    session.ProgramId = id; SaveDeploymentSession(file, session);
                }
                var payload = session.Original == null ? new JObject() : (JObject)session.Original.DeepClone();
                payload["Address"] = int.Parse(session.ProgramId); payload["Group"] = "Automan";
                payload["Type"] = program["language"]; payload["Name"] = program["name"]; payload["Description"] = program["description"];
                payload["ScriptSetup"] = program["setup"]; payload["ScriptSource"] = program["main"]; payload["ScriptContext"] = program["context"];
                payload["IsEnabled"] = false;
                var errors = DeploymentCompilerErrors(Api.Call("HomeAutomation.HomeGenie/Automation/Programs.Compile", payload.ToString(Formatting.None)));
                if (errors.Count > 0) {
                    session.State = "compile_failed"; result.State = "failed"; result.Error = "Program compilation failed.";
                    result.Response = new { status = "compile_failed", program_id = session.ProgramId, compiler_errors = errors };
                } else {
                    if (session.Original == null || session.Original["IsEnabled"]?.Value<bool>() == true)
                        RequireDeploymentSuccess(Api.Call("HomeAutomation.HomeGenie/Automation/Programs.Enable/" + session.ProgramId));
                    session.State = "completed"; result.State = "completed"; result.Success = true; result.Error = null;
                    result.Response = new { status = "success", program_id = session.ProgramId };
                }
            }
            SaveDeploymentSession(file, session);
        } catch (Exception ex) {
            result.State = mutationStarted ? "unknown" : "failed";
            result.Success = false; result.Error = ex.Message;
            result.Response = new { status = result.State, program_id = session?.ProgramId ?? "" };
        }
        result.DurationMs = clock.ElapsedMilliseconds; result.CompletedAt = DateTimeOffset.UtcNow;
        try { ActionLedger.Save(folder, records); }
        catch (Exception) { result.State = "unknown"; result.Success = false; result.Error = "Deployment result could not be persisted."; }
        return result;
    }
}

public static class GenieResponseContract
{
    static readonly string[] Kinds = { "reply", "device", "program", "widget", "composite", "context" };
    static void Fields(JObject value, params string[] allowed) {
        if (value.Properties().Any(p => !allowed.Contains(p.Name))) throw new InvalidOperationException("Unknown response field.");
    }
    static string Text(JObject value, string key, bool required = false) {
        if (value[key] != null && value[key].Type != JTokenType.String) throw new InvalidOperationException("Expected string: " + key);
        string text = (string)value[key] ?? "";
        if (required && string.IsNullOrWhiteSpace(text)) throw new InvalidOperationException("Missing response field: " + key);
        return text;
    }
    static bool EmptyArtifact(JToken value) {
        if (value == null || value.Type == JTokenType.Null) return true;
        if (value.Type == JTokenType.String) return string.IsNullOrWhiteSpace((string)value);
        if (value is JObject obj) return obj.Properties().All(p => EmptyArtifact(p.Value));
        if (value is JArray array) return array.All(EmptyArtifact);
        return false;
    }
    public static string[] DeviceCommand(string command) {
        string[] p = command.Split('/');
        if (p.Length >= 3 && p[0] == "HomeAutomation.HomeGenie" && p[1] == "Config" && p[2] == "Modules.ParameterSet") {
            if (p.Length != 7 || !System.Text.RegularExpressions.Regex.IsMatch(p[3], @"\A[A-Za-z][A-Za-z0-9_.:-]*\z")
                || !System.Text.RegularExpressions.Regex.IsMatch(p[4], @"\A[A-Za-z0-9_.:-]+\z")
                || !System.Text.RegularExpressions.Regex.IsMatch(p[5], @"\A[A-Za-z][A-Za-z0-9_.-]*\z")
                || p.Skip(6).Any(v => !System.Text.RegularExpressions.Regex.IsMatch(v, @"\A(?:On|Off|-?[0-9]+(?:\.[0-9]+)?)\z") || v.Length > 64))
                throw new InvalidOperationException("Invalid module configuration command.");
            return new[]{p[3],p[4]};
        }
        if (p.Length < 3) throw new InvalidOperationException("Invalid device command.");
        if (p[0] == "HomeAutomation.HomeGenie" && p[1] == "Automation" && new[]{"Programs.Run","Programs.Break"}.Contains(p[2])) {
            if (p.Length != 4 || !System.Text.RegularExpressions.Regex.IsMatch(p[3],@"^[1-9][0-9]*$")) throw new InvalidOperationException("Invalid scene target.");
            return new[]{"HomeAutomation.HomeGenie.Automation",p[3]};
        }
        string[] simple = {"Control.On","Control.Off","Control.Toggle","Control.ArmAway","Control.ArmHome","Control.Disarm"};
        if (simple.Contains(p[2])) { if (p.Length != 3) throw new InvalidOperationException("Unexpected command arguments."); }
        else if (p[2] == "Control.Level") {
            if (p.Length != 4 || !double.TryParse(p[3],System.Globalization.NumberStyles.Float,System.Globalization.CultureInfo.InvariantCulture,out var level)
                || !double.IsFinite(level) || level < 0 || level > 100) throw new InvalidOperationException("Invalid brightness.");
        } else if (p[2] == "Control.ColorHsb") {
            if (p.Length != 4) throw new InvalidOperationException("Invalid color.");
            var values = p[3].Split(',');
            if (values.Length < 3 || values.Length > 4) throw new InvalidOperationException("Invalid color.");
            for (int i=0;i<values.Length;i++)
                if (!double.TryParse(values[i],System.Globalization.NumberStyles.Float,System.Globalization.CultureInfo.InvariantCulture,out var v)
                    || !double.IsFinite(v) || v < 0 || i < 3 && v > 1) throw new InvalidOperationException("Invalid color value.");
        } else if (p[2] == "Thermostat.ModeSet") {
            if (p.Length != 4 || !new[]{"Off","Heat","HeatEconomy","Cool","CoolEconomy"}.Contains(p[3])) throw new InvalidOperationException("Invalid thermostat mode.");
        } else if (p[2] == "Thermostat.SetPointSet") {
            if (p.Length != 5 || !new[]{"Heating","Cooling"}.Contains(p[3]) || !double.TryParse(p[4],System.Globalization.NumberStyles.Float,System.Globalization.CultureInfo.InvariantCulture,out var t) || !double.IsFinite(t)) throw new InvalidOperationException("Invalid thermostat setpoint.");
        } else throw new InvalidOperationException("Unsupported device command.");
        return new[]{p[0],p[1]};
    }
    public static JObject Normalize(JObject input) {
        if (input == null) throw new InvalidOperationException("A response object is required.");
        var result = (JObject)input.DeepClone();
        // Adapt legacy provider responses at the boundary; they remain independently usable.
        if (result["kind"] == null && result["solution_type"] != null) {
            result["kind"] = result["solution_type"]; result.Remove("solution_type"); result["version"] = 1;
            if (result["kind"]?.ToString() == "automation") {
                result["kind"] = "program";
                ((JObject)result["automation"])["action"] = "create";
            }
            if (result["kind"]?.ToString() == "composite") ((JObject)result["automation"])["action"] = "create";
        } else if (result["kind"] == null && result["action"] != null) {
            string action = Text(result, "action", true);
            result = new JObject { ["version"] = 1, ["kind"] = action == "reply" ? "reply" : "program",
                ["explanation"] = Text(input, "explanation", true), ["language"] = Text(input, "language") };
            if (action != "reply") result["automation"] = new JObject {
                ["action"] = action, ["program_id"] = Text(input,"program_id"), ["name"] = Text(input,"name"),
                ["setup"] = Text(input,"setup"), ["main"] = Text(input,"main"), ["context"] = Text(input,"context")
            };
        }
        Fields(result,"version","kind","explanation","language","commands","automation","widget","binding","resources");
        if (result["version"]?.Type != JTokenType.Integer || (int)result["version"] != 1) throw new InvalidOperationException("Unsupported response contract version.");
        string kind = Text(result,"kind",true); Text(result,"explanation",true);
        if (!Kinds.Contains(kind)) throw new InvalidOperationException("Unsupported response kind.");
        var permitted = kind == "device" ? new[]{"commands"} : kind == "program" ? new[]{"automation"}
            : kind == "widget" ? new[]{"widget"} : kind == "composite" ? new[]{"automation","widget","binding"}
            : kind == "context" ? new[]{"resources"} : new string[0];
        foreach (string key in new[]{"commands","automation","widget","binding","resources"}) {
            if (result[key] == null || permitted.Contains(key)) continue;
            if (EmptyArtifact(result[key])) result.Remove(key);
            else throw new InvalidOperationException("Artifact is incompatible with response kind: " + key);
        }
        if (kind == "program" || kind == "composite") {
            if (!(result["automation"] is JObject a)) throw new InvalidOperationException("Missing automation.");
            Fields(a,"action","program_id","name","setup","main","context");
            string action=Text(a,"action",true), id=Text(a,"program_id");
            if (!new[]{"create","update"}.Contains(action) || kind == "composite" && action != "create") throw new InvalidOperationException("Unsupported deployment action.");
            if (action == "create" && id.Length != 0 || action == "update" && !System.Text.RegularExpressions.Regex.IsMatch(id,@"^[1-9][0-9]*$")) throw new InvalidOperationException("Invalid deployment target.");
            Text(a,"name",true); Text(a,"main",true); Text(a,"context");
            if (a["setup"] == null) throw new InvalidOperationException("Missing setup."); Text(a,"setup");
            if (!new[]{"csharp","python","javascript"}.Contains(Text(result,"language",true))) throw new InvalidOperationException("Unsupported program language.");
            a["program_id"]=id; a["context"]=Text(a,"context");
        }
        if (kind == "widget" || kind == "composite") {
            if (!(result["widget"] is JObject w)) throw new InvalidOperationException("Missing widget.");
            Fields(w,"html","css","javascript","mode");Text(w,"html",true);Text(w,"javascript",true);w["css"]=Text(w,"css");
            if (w["mode"] != null && Text(w,"mode",true) != "presentation")
                throw new InvalidOperationException("Unsupported widget mode.");
        }
        if (kind == "composite") {
            if (!(result["binding"] is JObject binding)) throw new InvalidOperationException("Missing binding.");
            Fields(binding,"domain","address","properties");Text(binding,"domain",true);Text(binding,"address",true);
            if (!(binding["properties"] is JArray props) || props.Count==0 || props.Count>32 || props.Any(p=>p.Type!=JTokenType.String || string.IsNullOrWhiteSpace((string)p))) throw new InvalidOperationException("Invalid binding properties.");
        }
        if (kind == "device") {
            if (!(result["commands"] is JArray commands) || commands.Count==0 || commands.Count>32 || commands.Any(c=>c.Type!=JTokenType.String || !System.Text.RegularExpressions.Regex.IsMatch((string)c,@"^[A-Za-z][A-Za-z0-9_.:-]*/[^/\s]+/[^/\s]+(?:/[^\r\n]*)?$"))) throw new InvalidOperationException("Invalid device commands.");
            foreach (string command in commands.Values<string>()) DeviceCommand(command);
        }
        if (kind == "context") {
            if (!(result["resources"] is JObject r)) throw new InvalidOperationException("Missing context resources.");
            Fields(r,"programIds","widgetIds","moduleIds","parameterIds");int count=0;
            foreach (var p in r.Properties()) {
                if (!(p.Value is JArray ids) || ids.Count>16 || ids.Any(i=>i.Type!=JTokenType.String || string.IsNullOrWhiteSpace((string)i))) throw new InvalidOperationException("Invalid resource identifiers.");
                count+=ids.Count;
            }
            if (count==0) throw new InvalidOperationException("Empty context lookup.");
        }
        if (Encoding.UTF8.GetByteCount(result.ToString(Formatting.None))>512*1024) throw new InvalidOperationException("Response exceeds size limit.");
        return result;
    }
    public static JObject LegacyArtifacts(JObject normalized) {
        var result=(JObject)normalized.DeepClone();string kind=(string)result["kind"];
        result.Remove("version");result.Remove("kind");result["solution_type"]=kind == "program" ? "automation" : kind;
        if (result["automation"] is JObject a) { a.Remove("action");a.Remove("program_id"); }
        return result;
    }
    public static JObject Schema() {
        var prototype = JObject.Parse(@"{
          'type':'object','properties':{
            'version':{'type':'integer'},'kind':{'type':'string','enum':['reply','device','program','widget','composite','context']},
            'explanation':{'type':'string'},'language':{'type':'string','enum':['csharp','python','javascript']},
            'commands':{'type':'array','items':{'type':'string'}},
            'automation':{'type':'object','properties':{'action':{'type':'string','enum':['create','update']},'program_id':{'type':'string'},'name':{'type':'string'},'setup':{'type':'string'},'main':{'type':'string'},'context':{'type':'string'}},'required':['action','name','setup','main']},
            'widget':{'type':'object','properties':{'html':{'type':'string'},'css':{'type':'string'},'javascript':{'type':'string'},'mode':{'type':'string','enum':['presentation']}},'required':['html','css','javascript']},
            'binding':{'type':'object','properties':{'domain':{'type':'string'},'address':{'type':'string'},'properties':{'type':'array','items':{'type':'string'}}},'required':['domain','address','properties']},
            'resources':{'type':'object','properties':{'programIds':{'type':'array','items':{'type':'string'}},'widgetIds':{'type':'array','items':{'type':'string'}},'moduleIds':{'type':'array','items':{'type':'string'}},'parameterIds':{'type':'array','items':{'type':'string'}}}}
          },'required':['version','kind','explanation']
        }");
        var variants = new JArray();
        foreach (string kind in Kinds) {
            var fields = new List<string> { "version", "kind", "explanation" };
            if (kind == "device") fields.Add("commands");
            if (kind == "program" || kind == "composite") { fields.Add("language"); fields.Add("automation"); }
            if (kind == "widget" || kind == "composite") fields.Add("widget");
            if (kind == "composite") fields.Add("binding");
            if (kind == "context") fields.Add("resources");
            var properties = new JObject(fields.Select(f => new JProperty(f, prototype["properties"][f].DeepClone())));
            properties["kind"]["enum"] = new JArray(kind);
            variants.Add(new JObject { ["type"]="object", ["properties"]=properties, ["required"]=new JArray(fields), ["additionalProperties"]=false });
        }
        return new JObject { ["anyOf"] = variants };
    }
}

public static class ModuleSettingAction
{
    static JObject Object(object value) => value is string text ? JObject.Parse(text) : JObject.FromObject(value);
    static string Read(dynamic api, string domain, string address, string key) {
        JObject result = Object(api.Call("HomeAutomation.HomeGenie/Config/Modules.ParameterGet/" + domain + "/" + address + "/" + key + "/Context"));
        if ((int?)result["version"] != 1 || (string)result["domain"] != domain || (string)result["address"] != address
            || (string)result["key"] != key || result["present"]?.Value<bool>() != true || result["value"]?.Type != JTokenType.String)
            throw new InvalidOperationException("A current readable existing setting is required.");
        return (string)result["value"];
    }
    public static void Validate(JObject description, string domain, string address, string key, string value) {
        if ((int?)description["version"] != 1 || (string)description["module"]?["domain"] != domain || (string)description["module"]?["address"] != address)
            throw new InvalidOperationException("Invalid module description.");
        var fields = description["features"] as JArray;
        var field = fields?.OfType<JObject>().SingleOrDefault(p => (string)p["key"] == key);
        if (field == null || field["sensitive"]?.Value<bool>() != false || field["present"]?.Value<bool>() != true
            || Regex.IsMatch(key, @"(?i)(password|passwd|secret|api[._-]?key|access[._-]?token|refresh[._-]?token|private[._-]?key|credential)"))
            throw new InvalidOperationException("Setting is unavailable or sensitive.");
        var programs = field["programs"] as JArray;
        if (programs == null || programs.Count == 0 || programs.Any(p => p["enabled"]?.Value<bool>() != true))
            throw new InvalidOperationException("An active applicable feature must declare the setting.");
        foreach (var feature in programs) {
            var type = ((string)feature["fieldType"] ?? "").Split(':');
            if (type[0] == "checkbox") {
                if (value != "On" && value != "Off") throw new InvalidOperationException("Use On or Off.");
            } else if (type[0] == "slider" && type.Length >= 4) {
                decimal Number(string text) => decimal.Parse(text, System.Globalization.NumberStyles.AllowLeadingSign | System.Globalization.NumberStyles.AllowDecimalPoint, System.Globalization.CultureInfo.InvariantCulture);
                decimal min=Number(type[1]),max=Number(type[2]),step=Number(type[3]),number=Number(value);
                if(step<=0 || min>max || number<min || number>max || (number-min)%step!=0) throw new InvalidOperationException("Setting is outside its declared range or step.");
            } else throw new InvalidOperationException("Only checkbox and bounded slider settings are supported.");
        }
    }
    public static JObject Execute(dynamic api, string command) {
        bool writing=false;
        var result=new JObject{["version"]=1,["verified"]=false,["state"]="failed",["Status"]="Error"};
        try {
            GenieResponseContract.DeviceCommand(command);
            var p=command.Split('/'); string domain=p[3],address=p[4],key=p[5],value=p[6];
            result["domain"]=domain;result["address"]=address;result["key"]=key;result["requestedValue"]=value;
            JObject description=Object(api.Call("HomeAutomation.HomeGenie/Config/Modules.Get/"+domain+"/"+address+"/Schema"));
            Validate(description,domain,address,key,value);
            string previous=Read(api,domain,address,key);result["previousValue"]=previous;
            if(Read(api,domain,address,key)!=previous) throw new InvalidOperationException("Setting changed during validation; read again before retrying.");
            writing=true;
            JObject saved=Object(api.Call(command));
            string status=(string)saved["Status"];
            if(status!="0" && !string.Equals(status,"OK",StringComparison.OrdinalIgnoreCase)) throw new InvalidOperationException("ParameterSet did not confirm the write.");
            string actual=Read(api,domain,address,key);result["value"]=actual;
            if(actual!=value) throw new InvalidOperationException("Setting readback does not match.");
            result["verified"]=true;result["state"]="completed";result["Status"]="OK";
        } catch(Exception error) {
            result["state"]=writing?"unknown":"failed";
            result["Message"]=writing?"Configuration outcome is uncertain; read the setting before retrying.":error.Message;
        }
        return result;
    }
}

ProgramBlock.ScriptSetup:
Program.Setup(() => {
    Program.Implements("@Service:Notifications", "System.Utility/Notifications", new { version = 1 });
    Program.AddOption("MaximumItems", "500", "Maximum archived notifications", "text");
    Program.AddOption("RetentionDays", "90", "Notification retention (days)", "text");
});
Program.Run();

ProgramBlock.ScriptSource:
string path = Path.Combine(Data.GetFolder(), "notifications.json");
int limit=500,days=90;if(!int.TryParse(Program.Option("MaximumItems").Value,out limit))limit=500;if(!int.TryParse(Program.Option("RetentionDays").Value,out days))days=90;limit=Math.Clamp(limit,10,5000);days=Math.Clamp(days,1,3650);
JArray rows;var recovered=new List<JObject>();lock(NotificationArchive.Gate){rows=NotificationArchive.Load(path);foreach(JObject row in rows)if(NotificationArchive.Recover(row))recovered.Add((JObject)row.DeepClone());NotificationArchive.Save(path,rows);}
Func<object,JObject> parse = input => {
    var data=Api.Parse(input)?.Data;
    return data is byte[] b ? JObject.Parse(Encoding.UTF8.GetString(b)) : data is string t && !string.IsNullOrWhiteSpace(t)?JObject.Parse(t):data==null?new JObject():JObject.FromObject(data);
};
Action<JObject> announce = row => Program.Emit("Notification.ArchiveChanged",row.ToString(Formatting.None));
foreach(var row in recovered)announce(row);
Api.Handle("System.Utility/Notifications/List", input=>{lock(NotificationArchive.Gate){int before=rows.Count;NotificationArchive.Prune(rows,DateTime.UtcNow,limit,days);if(rows.Count!=before)NotificationArchive.Save(path,rows);return new JArray(rows.OfType<JObject>().Where(row => row["deleted"]?.Value<bool>() != true).Select(row => row.DeepClone()));}});
Api.Handle("System.Utility/Notifications/Get", input=>{try{lock(NotificationArchive.Gate){return NotificationArchive.Find(rows,parse(input)).DeepClone();}}catch(Exception e){return new ResponseStatus(Status.Error,e.Message);}});
foreach(var operation in new[]{"Read","Archive","Delete"}) {
    string op=operation;
    Api.Handle("System.Utility/Notifications/"+op,input=>{
        try {
            JArray changed; bool batch;
            lock(NotificationArchive.Gate) {
                var req=parse(input); batch=req["keys"] != null;
                var nextRows=(JArray)rows.DeepClone();
                changed=NotificationArchive.Manage(nextRows,req,op,DateTime.UtcNow);
                NotificationArchive.Save(path,nextRows); NotificationArchive.CommitManagement(rows,changed,op);
            }
            foreach(JObject row in changed)announce(row);
            return batch ? (object)new JObject { ["Status"]="Ok", ["items"]=changed } : changed[0];
        } catch(Exception e){return new ResponseStatus(Status.Error,e.Message);}
    });
}
Api.Handle("System.Utility/Notifications/Execute", input=>{
    JObject row=null,action=null,state=null,started=null;string id;
    try {
