    } catch (System.Threading.ThreadInterruptedException) { throw; }
    catch (Exception e) {
        if (Program.IsRunning && lastJobNoticeError != e.Message) { Program.Log.Error("Program update job notification: " + e.Message); lastJobNoticeError = e.Message; }
