            p["Persistent"]?.Type != JTokenType.Boolean || p["Persistent"].Value<bool>() != true) return null;
        var id=(string)p["Id"]; if(string.IsNullOrWhiteSpace(id)||id.Length>128)throw new InvalidOperationException("Persistent notification requires an Id (max 128 characters).");
        foreach(var key in new[]{"Title","Message"})if(p[key]?.Type!=JTokenType.String || ((string)p[key]).Length>16384)throw new InvalidOperationException("Invalid notification "+key);
        string severity=(string)p["Severity"]??"info";if(!new[]{"info","success","warning","error"}.Contains(severity))throw new InvalidOperationException("Invalid severity.");p["Severity"]=severity;
        if (p["Actions"] != null && p["Actions"].Type != JTokenType.Null && p["Actions"].Type != JTokenType.Array) throw new InvalidOperationException("Actions must be an array.");
        var actions=p["Actions"] as JArray ?? new JArray(); if(actions.Count>4)throw new InvalidOperationException("Maximum four notification actions.");
        var ids=new HashSet<string>();foreach(var item in actions) {
            var action = item as JObject; if (action == null) throw new InvalidOperationException("Each action must be an object.");
            var aid=(string)action["Id"];if(string.IsNullOrWhiteSpace(aid)||aid.Length>64||!ids.Add(aid))throw new InvalidOperationException("Invalid action Id.");
            if(action["Label"]?.Type!=JTokenType.String || ((string)action["Label"]).Length>256)throw new InvalidOperationException("Invalid action label.");
            if ((string)action["Type"] == "navigate") {
                if ((string)action["Destination"] != "program-updates" || action["Endpoint"] != null || action["Body"] != null)
                    throw new InvalidOperationException("Invalid navigation destination.");
                continue;
            }
            if((string)action["Type"]!="api" || (string)action["Method"]!="POST")throw new InvalidOperationException("Only local POST API actions are supported.");
            var endpoint=(string)action["Endpoint"];
            if(endpoint==null||endpoint.Length>256||!Regex.IsMatch(endpoint,@"^[A-Za-z][A-Za-z0-9_.:-]*(/[A-Za-z0-9_.-]+){2,}$")||endpoint.Contains(".."))throw new InvalidOperationException("Invalid local action endpoint.");
            if(action["Body"]!=null && action["Body"].Type!=JTokenType.Null && action["Body"].Type!=JTokenType.Object)throw new InvalidOperationException("Action Body must be an object.");
            if(action["Idempotent"]!=null && action["Idempotent"].Type!=JTokenType.Boolean)throw new InvalidOperationException("Idempotent must be boolean.");
        }
        p["Actions"]=actions;return p;
    }
    public static JArray Read(string path) {
        return JsonConvert.DeserializeObject<JArray>(File.ReadAllText(path),new JsonSerializerSettings{DateParseHandling=DateParseHandling.None})
            ?? throw new JsonSerializationException("Notification archive must contain an array.");
    }
    public static JArray Load(string path) {
        if(!File.Exists(path))return File.Exists(path+".bak")?Read(path+".bak"):new JArray();
        try{return Read(path);}catch {if(File.Exists(path+".bak"))return Read(path+".bak");throw;}
    }
    public static void Save(string path,JArray records) {
        Directory.CreateDirectory(Path.GetDirectoryName(path));string temp=path+".tmp";
        var bytes=Encoding.UTF8.GetBytes(records.ToString(Formatting.None));
        using(var file=new FileStream(temp,FileMode.Create,FileAccess.Write,FileShare.None)){file.Write(bytes,0,bytes.Length);file.Flush(true);}
        if(File.Exists(path)){bool valid=true;try{Read(path);}catch{valid=false;}if(valid)File.Copy(path,path+".bak",true);}
