    }
    public static JObject Upsert(JArray records,JObject payload,string domain,string address,DateTime now,int limit,int days) {
        var identity=domain+"\n"+address+"\n"+(string)payload["Id"];
        var key=Convert.ToHexString(SHA256.HashData(Encoding.UTF8.GetBytes(identity))).ToLowerInvariant();
        var row=records.OfType<JObject>().FirstOrDefault(r=>(string)r["key"]==key);bool fresh=row==null;
        if (!fresh && row["deleted"]?.Value<bool>() == true) {
            if (SameDeletedPayload(row,payload)) return row;
            if (payload["Sequence"]?.Type == JTokenType.Integer && row["payload"]?["Sequence"]?.Type == JTokenType.Integer &&
                payload["Sequence"].Value<long>() <= row["payload"]["Sequence"].Value<long>()) return row;
            row.Remove("deleted"); row.Remove("deletedHash"); row.Remove("deletedAt");
            row["createdAt"]=now.ToString("O"); row["count"]=0;
        }
        // Producers may provide a sequence so asynchronous event delivery cannot regress progress.
        if (!fresh && payload["Sequence"]?.Type == JTokenType.Integer && row["payload"]?["Sequence"]?.Type == JTokenType.Integer &&
            payload["Sequence"].Value<long>() <= row["payload"]["Sequence"].Value<long>()) return row;
        if(fresh){row=new JObject{["key"]=key,["domain"]=domain,["address"]=address,["createdAt"]=now.ToString("O"),["revision"]=0,["count"]=0,["read"]=false,["archived"]=false,["actionStates"]=new JObject(),["actionRuns"]=new JArray()};records.Add(row);}
        if(fresh||!JToken.DeepEquals(row["payload"],payload)) {
