            row["payload"]=payload.DeepClone();row["revision"]=(int)row["revision"]+1;row["read"]=false;row["archived"]=false;
            if(!sameActions)row["actionStates"]=new JObject();
        }
        row["sequence"]=(row["sequence"]?.Value<long>()??0)+1;
        row["updatedAt"]=now.ToString("O");row["count"]=(int)row["count"]+1;
