        return row;
    }
    public static void Prune(JArray records,DateTime now,int limit,int days,JObject keep=null) {
        foreach(var old in records.OfType<JObject>().Where(r=>r!=keep&&!Running(r)&&DateTime.Parse((string)r["updatedAt"]).ToUniversalTime()<now.AddDays(-days)).ToList())records.Remove(old);
        while(records.OfType<JObject>().Count(r=>r["deleted"]?.Value<bool>()!=true)>limit){var oldest=records.OfType<JObject>().Where(r=>r!=keep&&!Running(r)&&r["deleted"]?.Value<bool>()!=true).OrderByDescending(r=>r["archived"]?.Value<bool>()==true).ThenBy(r=>(string)r["updatedAt"]).FirstOrDefault();if(oldest==null)break;records.Remove(oldest);}
    }
    public static JObject Find(JArray rows,JObject request) {
        var row=rows.OfType<JObject>().FirstOrDefault(r=>(string)r["key"]==(string)request["key"]&&r["deleted"]?.Value<bool>()!=true);if(row==null)throw new InvalidOperationException("Notification no longer available.");return row;
    }
    // Retain only identity and a content fingerprint to prevent recovery from resurrecting a deleted notice.
    // These markers expire with the normal retention period and are never returned by List.
    private static JToken Canonical(JToken token) {
        if(token is JObject obj)return new JObject(obj.Properties().OrderBy(p=>p.Name,StringComparer.Ordinal).Select(p=>new JProperty(p.Name,Canonical(p.Value))));
        if(token is JArray array)return new JArray(array.Select(Canonical));
        return token.DeepClone();
    }
    public static string PayloadHash(JObject payload) => Convert.ToHexString(SHA256.HashData(Encoding.UTF8.GetBytes(Canonical(payload).ToString(Formatting.None))));
    public static bool SameDeletedPayload(JObject row,JObject payload) => row["deleted"]?.Value<bool>()==true && (string)row["deletedHash"]==PayloadHash(payload);
    public static JArray Manage(JArray rows,JObject request,string operation,DateTime now) {
        if(!new[]{"Read","Archive","Delete"}.Contains(operation))throw new InvalidOperationException("Unknown notification operation.");
        var keys=request["keys"]==null?new JArray(request["key"]):request["keys"] as JArray;
        if(keys==null||keys.Count==0||keys.Count>500||keys.Any(k=>k.Type!=JTokenType.String||string.IsNullOrWhiteSpace((string)k))||keys.Select(k=>(string)k).Distinct().Count()!=keys.Count)
            throw new InvalidOperationException("Select between one and 500 distinct notifications.");
        var selected=keys.Select(key=>rows.OfType<JObject>().FirstOrDefault(r=>(string)r["key"]==(string)key) ?? throw new InvalidOperationException("Notification no longer available.")).ToList();
        if(selected.Any(row=>operation!="Delete" && row["deleted"]?.Value<bool>()==true))throw new InvalidOperationException("Notification no longer available.");
        if(operation!="Read" && selected.Any(Running))throw new InvalidOperationException("A notification action is still running.");
        if(request["value"]!=null && request["value"].Type!=JTokenType.Boolean)throw new InvalidOperationException("Notification value must be boolean.");
        var changed=new JArray();
        foreach(var row in selected) {
            if(operation=="Delete" && row["deleted"]?.Value<bool>()!=true) {
                var key=row["key"].DeepClone();var domain=row["domain"].DeepClone();var address=row["address"].DeepClone();
                var id=row["payload"]["Id"].DeepClone();var producerSequence=row["payload"]?["Sequence"]?.DeepClone();
                var hash=PayloadHash((JObject)row["payload"]);var sequence=row["sequence"]?.Value<long>()??0;var revision=row["revision"]?.Value<int>()??0;
                row.RemoveAll();row["key"]=key;row["domain"]=domain;row["address"]=address;row["deleted"]=true;row["deletedHash"]=hash;
                row["createdAt"]=now.ToString("O");row["updatedAt"]=now.ToString("O");row["deletedAt"]=now.ToString("O");
                row["sequence"]=sequence;row["revision"]=revision;row["read"]=true;row["archived"]=true;row["count"]=0;
                row["actionStates"]=new JObject();row["actionRuns"]=new JArray();
                row["payload"]=new JObject{["Version"]=1,["Id"]=id};
                if(producerSequence!=null)row["payload"]["Sequence"]=producerSequence;
