    }
    public static void CommitManagement(JArray rows,JArray changed,string operation) {
        foreach(JObject copy in changed) {
            var row=rows.OfType<JObject>().First(r=>(string)r["key"]==(string)copy["key"]);
            if(operation=="Delete") { row.RemoveAll();foreach(var property in copy.Properties())row[property.Name]=property.Value.DeepClone(); }
            else { string field=operation=="Read"?"read":"archived";row[field]=copy[field].DeepClone();row["sequence"]=copy["sequence"].DeepClone(); }
        }
    }
    public static JArray Runs(JObject row) {
        var runs=row["actionRuns"] as JArray;
        if(runs!=null)return runs;
        runs=new JArray();row["actionRuns"]=runs;
        foreach(var existing in ((JObject)row["actionStates"]).Properties().ToList()) {
            var state=(JObject)existing.Value.DeepClone();state["actionId"]=existing.Name;state["revision"]=row["revision"];
            state["runId"]=state["runId"]??Guid.NewGuid().ToString("N");runs.Add(state);row["actionStates"][existing.Name]=state.DeepClone();
        }
