    }
    public static void Sync(JObject row,JObject state) {
        string actionId=(string)state["actionId"];
        if((string)row["actionStates"]?[actionId]?["runId"]==(string)state["runId"])row["actionStates"][actionId]=state.DeepClone();
        row["sequence"]=(row["sequence"]?.Value<long>()??0)+1;
