    }
    public static bool Recover(JObject row) {
        if(row["deleted"]?.Value<bool>()==true)return false;
        bool changed=row["actionRuns"]==null;
        foreach(JObject state in Runs(row))if((string)state["state"]=="running"){state["state"]="unknown";Sync(row,state);changed=true;}
        return changed;
    }
    public static bool Running(JObject row) => (row["actionRuns"] as JArray)?.Any(r=>(string)r["state"]=="running")==true;
    public static JToken BoundedResult(JToken token,bool failed) {
        if(token.ToString(Formatting.None).Length<=16384)return token;
        string message=token is JObject obj && obj["Message"]?.Type==JTokenType.String?(string)obj["Message"]:"Action response retained without its large body.";
        return new JObject{["Status"]=failed?"Error":"Ok",["Message"]=message.Substring(0,Math.Min(1000,message.Length)),["truncated"]=true};
    }

}

public static class ProgramUpdateNotification {
    public const string Id = "program-updates-available";

    // Null means the check could not establish a complete, current result.
    // Never resolve an existing notice using an incomplete report.
    public static JObject Reconcile(JArray rows, JObject report, string domain, string address,
        DateTime now, int limit, int days) {
        if ((string)report?["Status"] != "Ok" || report?["complete"]?.Type != JTokenType.Boolean ||
            report["complete"].Value<bool>() != true || report["items"] is not JArray items ||
            report["fingerprint"]?.Type != JTokenType.String || string.IsNullOrWhiteSpace((string)report["fingerprint"])) return null;
        var existing = rows.OfType<JObject>().FirstOrDefault(r => (string)r["domain"] == domain &&
            (string)r["address"] == address && (string)r["payload"]?["Id"] == Id);
        if (items.Count == 0) {
            if (existing == null || existing["resolved"]?.Value<bool>() == true) return null;
            existing["archived"] = true;
            existing["resolved"] = true;
            existing["sequence"] = (existing["sequence"]?.Value<long>() ?? 0) + 1;
            existing["updatedAt"] = now.ToString("O");
            return existing;
        }
        var payload = new JObject {
            ["Version"] = 1, ["Persistent"] = true, ["Id"] = Id,
            ["Title"] = "Program updates available", ["TitleKey"] = "upgradable_programs",
            ["Message"] = "Updates are available. Review the programs before installing them.",
            ["MessageKey"] = "updates_available", ["Severity"] = "info",
            ["UpdateFingerprint"] = (string)report["fingerprint"],
            ["Actions"] = new JArray(new JObject {
                ["Id"] = "show-updates", ["Type"] = "navigate", ["Destination"] = "program-updates",
                ["Label"] = "Show upgradable programs", ["LabelKey"] = "show_upgradable_programs"
            })
        };
        if (existing != null && NotificationArchive.SameDeletedPayload(existing,payload)) return null;
        if (existing != null && existing["resolved"]?.Value<bool>() != true &&
            JToken.DeepEquals(existing["payload"], payload)) return null;
        bool wasResolved = existing?["resolved"]?.Value<bool>() == true;
        var row = NotificationArchive.Upsert(rows, NotificationArchive.Decode(payload.ToString()), domain, address, now, limit, days);
        if (wasResolved) { row["archived"] = false; row["read"] = false; row["revision"] = (int)row["revision"] + 1; }
        row["resolved"] = false;
        return row;
    }
}

