Program.Implements("@Service:AiGenie", "System.Utility/AiGenie", new { version = 1 })
    .AddOption("DefaultProvider", "940", "Default AI Genie", "select:");
Program.Run();

ProgramBlock.ScriptSource:
var service = new AiGenieService();
var requests = new AiGenieRequests();
var lifecycle = new AiGenieProgramLifecycle();
var providerOptionsGate=new object();
int providerOptionsPending=0;
Action refreshProviderOptions=()=> {
    lock(providerOptionsGate) {
        try {
            object raw=Api.Call("HomeAutomation.HomeGenie/Automation/Programs.Implements/^@AI:/regex");
            var providers=raw as JArray ?? (raw is string text?JToken.Parse(text) as JArray:raw==null?null:JToken.FromObject(raw) as JArray);
            if(providers==null)return;
            string selected=Program.Option("DefaultProvider").Value;
            string fieldType=AiGenieProviderOptions.Build(providers,selected);
            Program.AddOption("DefaultProvider","940","Default AI Genie",fieldType);
        } catch(Exception ex) {try {Program.Log.Warn("Could not refresh AI Genie provider options: "+ex.Message);}catch {}}
    }
};
refreshProviderOptions();
When.ProgramStopping(() => { lifecycle.Stop(); requests.Dispose(); service.Dispose(); return true; });
When.ModuleParameterChanged((module, parameter) => {
    if(module.Instance==null)return true;
    string domain=module.Instance.Domain, childId=module.Instance.Address;
    string field=parameter.Name, value=parameter.Value, serviceId=Program.Module.Address;
    // Provider registrations may complete after this utility starts. Refresh on lifecycle events, not a polling loop.
    if(domain=="HomeAutomation.HomeGenie.Automation" && field=="Program.Status" &&
        System.Threading.Interlocked.CompareExchange(ref providerOptionsPending,1,0)==0)
        System.Threading.Tasks.Task.Run(()=> {
            try {if(Program.IsRunning)refreshProviderOptions();}
            finally {System.Threading.Interlocked.Exchange(ref providerOptionsPending,0);}
        });
    if(AiGenieProgramLifecycle.IsQuit(domain,childId,field,value,serviceId))
        System.Threading.Tasks.Task.Run(() => {
            try {
                lifecycle.Handle(domain,childId,field,value,serviceId,route=> {
                    Api.Call(route);
                    Program.Log.Info($"Child program {childId} disabled after Quit request.");
                });
            } catch(Exception ex) {try {Program.Log.Error($"Error disabling child program {childId}: {ex.Message}");}catch {}}
        });
    return true;
});
